// face-blend: a floor sheet and two parallel upright sheets standing on it 20 mm apart, blended 3 mm, a help point at (15, 18, 1) picking one
export function c004(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
