    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(s2, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skLineSegment(s2, "l2", { "start" : vector(0, 20) * millimeter, "end" : vector(30, 20) * millimeter });
    skSolve(s2);
    extrude(context, id + "walls", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 15 * millimeter, "oppositeDirection" : false });
    opPoint(context, id + "help", { "point" : vector(15, 18, 1) * millimeter });
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : false, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "walls", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "radius" : 3 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "hasHelpPoint" : true, "helpPoint" : qCreatedBy(id + "help", EntityType.VERTEX) });
    return { "floor" : faceProbe(context, qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET)), "walls" : faceProbe(context, qBodyType(qCreatedBy(id + "walls", EntityType.BODY), BodyType.SHEET)) };
}

